const updatePerson = `-- name: UpdatePerson :exec
UPDATE people
SET name = ?,
    sort_name = ?,
    photo_path = ?,
    photo_url = ?,
    imdb_id = ?,
    tmdb_id = ?,
    updated_at = CURRENT_TIMESTAMP
WHERE id = ?
`

type UpdatePersonParams struct {
	Name      string         `json:"name"`
	SortName  sql.NullString `json:"sort_name"`
	PhotoPath sql.NullString `json:"photo_path"`
	PhotoUrl  sql.NullString `json:"photo_url"`
	ImdbID    sql.NullString `json:"imdb_id"`
	TmdbID    sql.NullInt64  `json:"tmdb_id"`
	ID        int64          `json:"id"`
}

func (q *Queries) UpdatePerson(ctx context.Context, arg UpdatePersonParams) error {
	_, err := q.db.ExecContext(ctx, updatePerson,
		arg.Name,
		arg.SortName,
		arg.PhotoPath,
		arg.PhotoUrl,
		arg.ImdbID,
		arg.TmdbID,
		arg.ID,
	)
	return err
}
